interface GeminiEvaluationContract {
  workflow: string;
  users: string[];
  outcome: string;
  requiredEvidence: string[];
  forbidden: string[];
  criteria: { quality: string; factuality: string; safety: string; permissions: string };
  budgets: { p95LatencyMs: number; maxTotalTokensPerCase: number };
  modalities: ("text" | "image" | "audio" | "video" | "document")[];
  slices: string[];
  mustNotRegress: string[]; // any failure blocks release regardless of the average
}

