import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
// Pinned separately from the candidate model. Verify current ids: https://ai.google.dev/gemini-api/docs/models
const graderModel = process.env.GEMINI_GRADER_MODEL;
if (!graderModel) throw new Error("GEMINI_GRADER_MODEL is not configured");
const GRADER_VERSION = "fault-support@v2";

// Model grader for a subjective rubric signal; deterministic checks handle schema, ids, and cost.
async function gradeFaultSupport(referenceAnnotation: string, feedback: string) {
  const interaction = await ai.interactions.create({
    model: graderModel,
    system_instruction: "Grade whether every fault in FEEDBACK appears in REFERENCE. Ignore style and tone.",
    input: `REFERENCE:\n${referenceAnnotation}\n\nFEEDBACK:\n${feedback}`,
    response_format: {
      type: "text",
      mime_type: "application/json",
      schema: {
        type: "object",
        properties: {
          supported: { type: "boolean" },
          unsupportedFaults: { type: "array", items: { type: "string" } },
        },
        required: ["supported", "unsupportedFaults"],
      },
    },
    store: false,
  });
  return { graderVersion: GRADER_VERSION, ...JSON.parse(interaction.output_text) };
}

// Calibrate before use: disagreement with blinded human labels, by slice and modality.
function disagreement(rows: { slice: string; modality: string; human: boolean; grader: boolean }[]) {
  const groups = Object.groupBy(rows, (row) => `${row.slice}/${row.modality}`);
  return Object.entries(groups).map(([group, g = []]) => ({
    group,
    rate: g.filter((row) => row.human !== row.grader).length / g.length,
  }));
}
// Groups above the agreed disagreement rate, and all high-impact cases, go to human review.

