// Allowlisted production event built from an Interaction: identifiers, versions, outcomes.
interface GeminiProductionEvent {
  traceId: string;
  interactionId?: string; // only when store is enabled
  appVersion: string;
  promptVersion: string;
  configuredModel: string;
  toolVersions: Record<string, string>;
  status: string; // completed, incomplete, failed, cancelled, ...
  modalities: string[];
  inputTokens?: number;
  outputTokens?: number;
  latencyMs: number;
  validation: "passed" | "failed";
  safetyEvent: boolean;
  terminalState: string;
  userFeedback?: "helpful" | "not_helpful" | "reported";
}

// The fields read from an Interactions API response.
interface InteractionResult {
  id: string;
  status: string;
  usage?: { total_input_tokens?: number; total_output_tokens?: number };
}

function toEvent(interaction: InteractionResult, ctx: RunContext): GeminiProductionEvent {
  return {
    traceId: ctx.traceId,
    interactionId: ctx.store ? interaction.id : undefined,
    appVersion: ctx.appVersion,
    promptVersion: ctx.promptVersion,
    configuredModel: ctx.model,
    toolVersions: ctx.toolVersions,
    status: interaction.status,
    modalities: ctx.modalities,
    inputTokens: interaction.usage?.total_input_tokens,
    outputTokens: interaction.usage?.total_output_tokens,
    latencyMs: ctx.latencyMs,
    validation: ctx.validationPassed ? "passed" : "failed",
    safetyEvent: ctx.safetyEvent,
    terminalState: ctx.terminalState,
    // No raw prompts, media, or outputs: those enter evaluation only after redaction and approval.
  };
}

// Drift is tracked per prompt version and modality; a breach pages an owner with a tested rollback.
function driftByModality(events: GeminiProductionEvent[], baselineFailureRate: number) {
  const byModality = Object.groupBy(events, (e) => e.modalities.join("+"));
  return Object.entries(byModality)
    .map(([modality, group = []]) => ({ modality, rate: group.filter((e) => e.validation === "failed").length / group.length }))
    .filter((row) => row.rate > baselineFailureRate * 1.5);
}
